type BaselineAggregatedCategory struct {
	// <p>Basic information of the baseline subcategory (including category ID, name, and description).</p>
	Category *BaselineCategory `json:"Category,omitnil,omitempty" name:"Category"`

	// <p>Distribution statistics of detection-failed items in this subcategory by risk level.</p>
	NotPassItemRiskLevelStatistic []*BaselineRiskLevelStatistic `json:"NotPassItemRiskLevelStatistic,omitnil,omitempty" name:"NotPassItemRiskLevelStatistic"`

	// <p>Number of detection items with a PASS result in this subcategory.</p>
	PassItemCount *uint64 `json:"PassItemCount,omitnil,omitempty" name:"PassItemCount"`

	// <p>Number of detection items with NOT_PASS result in this subcategory.</p>
	NotPassItemCount *uint64 `json:"NotPassItemCount,omitnil,omitempty" name:"NotPassItemCount"`

	// <p>Pass rate of detection items under this subcategory, unit: percentage (0-100), rounded to two decimal places.</p>
	PassRate *float64 `json:"PassRate,omitnil,omitempty" name:"PassRate"`

	// <p>Whether the baseline category has been scanned</p>
	Scanned *bool `json:"Scanned,omitnil,omitempty" name:"Scanned"`
}

type BaselineAggregatedItem struct {
	// <p>Basic detection item information (including ID, name, risk level, category, etc.).</p>
	Item *BaselineItem `json:"Item,omitnil,omitempty" name:"Item"`

	// <p>Number of assets with a PASS result in the last scan for this detection item.</p>
	PassAssetCount *uint64 `json:"PassAssetCount,omitnil,omitempty" name:"PassAssetCount"`

	// <p>Number of assets with result NOT_PASS in the last scan of this detection item.</p>
	NotPassAssetCount *uint64 `json:"NotPassAssetCount,omitnil,omitempty" name:"NotPassAssetCount"`

	// <p>Number of assets with the last scan result of PASS, NOT_PASS, and CHECKING for this detection item.</p>
	TotalAssetCount *uint64 `json:"TotalAssetCount,omitnil,omitempty" name:"TotalAssetCount"`

	// <p>Pass rate of assets in the last scan of this detection item, unit: percentage (0–100).</p>
	PassRate *float64 `json:"PassRate,omitnil,omitempty" name:"PassRate"`

	// <p>The last time the scan for this detection item was completed.</p>
	LatestCheckTime *string `json:"LatestCheckTime,omitnil,omitempty" name:"LatestCheckTime"`

	// <p>Status of the last scan result. Parameter Value:</p><ul><li>CHECKING: in-progress detection</li><li>PASS: passed</li><li>NOT_PASS: failed</li><li>CHECK_FAILED: detection failed</li><li>NOT_INVOLVED: not involved</li></ul>
	ResultStatus *string `json:"ResultStatus,omitnil,omitempty" name:"ResultStatus"`

	// <p>Tenant Appid list involved in the aggregation result.</p>
	Appid []*uint64 `json:"Appid,omitnil,omitempty" name:"Appid"`

	// <p>List of scan JobIDs involved in this aggregation result.</p>
	JobID []*string `json:"JobID,omitnil,omitempty" name:"JobID"`
}

type BaselineAggregatedPolicy struct {
	// <p>Parent category ID of the system policy (only for aggregation when PolicyType=SYSTEM; 0 for custom policy).</p>
	ParentCategoryID *uint64 `json:"ParentCategoryID,omitnil,omitempty" name:"ParentCategoryID"`

	// <p>List of baseline policy IDs involved in this aggregation.</p>
	PolicyID []*uint64 `json:"PolicyID,omitnil,omitempty" name:"PolicyID"`

	// <p>Policy Name (custom policy is user input, and system policy is a built-in classification name).</p>
	Name *string `json:"Name,omitnil,omitempty" name:"Name"`

	// <p>Policy description.</p>
	Description *string `json:"Description,omitnil,omitempty" name:"Description"`

	// <p>Number of detection items configured in the policy.</p>
	ConfItemCount *uint64 `json:"ConfItemCount,omitnil,omitempty" name:"ConfItemCount"`

	// <p>Number of detection items with a result of PASS under this policy.</p>
	PassItemCount *uint64 `json:"PassItemCount,omitnil,omitempty" name:"PassItemCount"`

	// <p>Number of detection items with result NOT_PASS under this policy.</p>
	NotPassItemCount *uint64 `json:"NotPassItemCount,omitnil,omitempty" name:"NotPassItemCount"`

	// <p>Distribution statistics of detection failed items by risk level (LOW/MEDIUM/HIGH/CRITICAL).</p>
	NotPassItemRiskLevelStatistic []*BaselineRiskLevelStatistic `json:"NotPassItemRiskLevelStatistic,omitnil,omitempty" name:"NotPassItemRiskLevelStatistic"`

	// <p>Passing rate of the last scan of this policy, unit: percentage (0-100), rounded to two decimal places.</p>
	PassRate *float64 `json:"PassRate,omitnil,omitempty" name:"PassRate"`

	// <p>Scanning result statistics details of each subcategory under this policy.</p>
	CategoryStatistic []*BaselineAggregatedCategory `json:"CategoryStatistic,omitnil,omitempty" name:"CategoryStatistic"`

	// <p>Baseline policy type. Values:</p><ul><li>SYSTEM: system policy (CSIP built-in)</li><li>SELF: user-defined policy</li></ul>
	PolicyType *string `json:"PolicyType,omitnil,omitempty" name:"PolicyType"`

	// <p>Detect asset major category, case-sensitive host baseline and container cluster baseline. Parameter values:</p><ul><li>HOST: Host</li><li>CLUSTER: Container cluster</li></ul>
	CheckAssetType *string `json:"CheckAssetType,omitnil,omitempty" name:"CheckAssetType"`

	// <p>Whether the baseline category has been scanned</p>
	Scanned *bool `json:"Scanned,omitnil,omitempty" name:"Scanned"`
}

